 const master='7'.repeat(64),credential='8'.repeat(64)+'.'+'9'.repeat(64);let publishOwner,view;const observed=[];
 const peer=createServer(async(request,response)=>{for await(const _ of request){}observed.push(request.headers.authorization);response.writeHead(200,{'Content-Type':'application/json'});if(request.url==='/v1/view-sessions'&&request.headers.authorization==='Bearer '+master){response.end(JSON.stringify({credential,expires_unix_ms:Date.now()+28800000,max_age_seconds:28800}));return;}if(request.url==='/v1/health'&&request.headers.authorization==='View '+credential){response.end(JSON.stringify({status:'ok'}));return;}response.statusCode=401;response.end('{}');});
