test('browser forwards revision-bound permission-grant DELETE bodies and blocks cross-origin revocation',async()=>{
 const {createNativeBrowserFixture}=await import('./native-host.mjs'),assetRoot=resolve(process.env.XMIND_BROWSER_TEST_ASSETS||'.agentflow/browser-assets'),master='permission-grant-proxy-master'.padEnd(64,'x'),credential='a'.repeat(64)+'.'+'b'.repeat(64);let view,viewOrigin,revocations=0;
 const peer=createServer(async(request,response)=>{let input='';for await(const chunk of request)input+=chunk;const reply=(status,data)=>{response.writeHead(status,{'Content-Type':'application/json'});response.end(JSON.stringify(data));};
  if(request.url==='/v1/view-sessions'){assert.equal(request.headers.authorization,'Bearer '+master);reply(200,{credential,expires_unix_ms:Date.now()+28800000,max_age_seconds:28800});return;}
  if(request.url==='/v1/sessions/session-a/permission-grants/grant_a'){assert.equal(request.method,'DELETE');assert.equal(request.headers.authorization,'View '+credential);assert.equal(request.headers['x-xmind-view-origin'],viewOrigin);assert.deepEqual(JSON.parse(input),{expected_revision:7});revocations++;reply(200,{session_id:'session-a',revision:8,grants:[]});return;}
  reply(404,{detail:'Unexpected fixture route'});
 });
 try{await new Promise(resolve=>peer.listen(0,'127.0.0.1',resolve));view=await createNativeBrowserFixture({backend:'http://127.0.0.1:'+peer.address().port,assetRoot,localAccessToken:master});viewOrigin=await view.listen();const base={Origin:viewOrigin,'Content-Type':'application/json','Sec-Fetch-Site':'same-origin'},login=await fetch(viewOrigin+'/ui/session',{method:'POST',headers:base,body:'{}'});assert.equal(login.status,200);const cookie=login.headers.get('set-cookie').split(';')[0];
  const foreign=await fetch(viewOrigin+'/v1/sessions/session-a/permission-grants/grant_a',{method:'DELETE',headers:{Cookie:cookie,Origin:'http://foreign.example','Sec-Fetch-Site':'same-origin','Content-Type':'application/json'},body:'{"expected_revision":7}'});assert.equal(foreign.status,403);assert.equal(revocations,0);
  const result=await fetch(viewOrigin+'/v1/sessions/session-a/permission-grants/grant_a',{method:'DELETE',headers:{Cookie:cookie,Origin:viewOrigin,'Sec-Fetch-Site':'same-origin','Content-Type':'application/json'},body:'{"expected_revision":7}'});assert.equal(result.status,200);assert.deepEqual(await result.json(),{session_id:'session-a',revision:8,grants:[]});assert.equal(revocations,1);
 }finally{if(view)await view.close();peer.closeAllConnections();await new Promise(resolve=>peer.close(resolve));}
});
